import tkinter as tkfrom tkinter import messageboximport pyDesimport binasciidef encrypt_text():    text = input_text.get()    key = key_text.get()    if len(key) != 8:        messagebox.showerror("Error", "Key must be 8 bytes long")        return    des = pyDes.des(key.encode(), pyDes.ECB)    encrypted_data = des.encrypt(text.ljust(8).encode())    encrypted_text.set(binascii.hexlify(encrypted_data).decode())def decrypt_text():    encrypted_hex = encrypted_text.get()    key = key_text.get()    if len(key) != 8:        messagebox.showerror("Error", "Key must be 8 bytes long")        return    des = pyDes.des(key.encode(), pyDes.ECB)    decrypted_data = des.decrypt(binascii.unhexlify(encrypted_hex)).decode().strip()    decrypted_text.set(decrypted_data)# GUI Setuproot = tk.Tk()root.title("DES Encryption & Decryption")# Input Texttk.Label(root, text="Input Text:").grid(row=0, column=0)input_text = tk.Entry(root, width=40)input_text.grid(row=0, column=1)# Key Inputtk.Label(root, text="8-Byte Key:").grid(row=1, column=0)key_text = tk.Entry(root, width=40)key_text.grid(row=1, column=1)# Encrypt Buttontk.Button(root, text="Encrypt", command=encrypt_text).grid(row=2, column=0, pady=10)# Encrypted Outputtk.Label(root, text="Encrypted Text:").grid(row=3, column=0)encrypted_text = tk.StringVar()tk.Entry(root, textvariable=encrypted_text, width=40, state="readonly").grid(row=3, column=1)# Decrypt Buttontk.Button(root, text="Decrypt", command=decrypt_text).grid(row=4, column=0, pady=10)# Decrypted Outputtk.Label(root, text="Decrypted Text:").grid(row=5, column=0)decrypted_text = tk.StringVar()tk.Entry(root, textvariable=decrypted_text, width=40, state="readonly").grid(row=5, column=1)root.mainloop()